code.cpp:
class Solution {
public:
    string removeDuplicates(string s) {
        int j = 0, n = s.size();
        for (int i = 0; i < n; i++) {
            if (j > 0 && s[j - 1] == s[i])
                j--;
            else
                s[j++] = s[i];
        }
        return s.substr(0, j);
    }
};
